    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A competent patient with end-stage renal disease decides to stop dialysis, knowing they will die. Is this considered "Suicide"?', '["Yes, legally and ethically", "No, it is a legal and ethical right to refuse medical treatment, even if that refusal leads to death", "Only if they have a mental illness", "Only if they are under 50"]', 1, 'Refusing life-sustaining treatment is an exercise of autonomy, distinct from the intentional act of self-destruction (suicide).'),
    (v_topic_id, 'Which of the following describes "VSED" as a way to hasten death?', '["Voluntarily Stopping Eating and Drinking", "Very Slow Emergency Delivery", "Venous Stasis and Edema", "None of the above"]', 0, 'VSED is a choice sometimes made by terminally ill patients to control the timing of their death without active euthanasia.'),
    (v_topic_id, 'A pregnant woman at 39 weeks refuses a C-section that is necessary to save the life of the fetus. She understands the risks and is competent. The physician should:', '["Perform the surgery anyway", "Respect her refusal, as competent pregnant women have the same right to bodily integrity as any other patient", "Ask the father to overrule her", "Seek an emergency court order immediately"]', 1, 'In US law, maternal autonomy is extremely high, and courts have consistently refused to force obstetric procedures over a competent woman''s objection.'),
    (v_topic_id, 'A Jehovah''s Witness patient is unconscious and bleeding profusely. No family or "Blood Card" is found. What should the physician do?', '["Withhold blood because most JW patients would refuse it", "Give blood under the ''Emergency Exception'' (Implied Consent), as there is no clear and convincing evidence of a specific refusal", "Wait for a witness", "None of the above"]', 1, 'In an emergency with no evidence of refusal, the default is to save the patient''s life.'),
    (v_topic_id, 'A 17-year-old "Mature Minor" who is a Jehovah''s Witness refuses a life-saving blood transfusion. His parents also refuse. The physician should:', '["Respect the refusal", "Seek a court order to treat the child, as the state''s interest in protecting the life of a minor generally overrides the religious beliefs of both the parent and the child in life-saving scenarios", "Do nothing", "None of the above"]', 1, 'While mature minors have some rights, the "Parens Patriae" duty for life-saving care is usually the legal override until age 18.'),
    (v_topic_id, 'A physician refuses to perform a "Legal Abortion" because of their own religious beliefs. This is known as:', '["Malpractice", "Conscientious Objection", "Abandonment", "None of the above"]', 1, 'Physicians have a right to refuse to participate in certain procedures that violate their core moral/religious beliefs, provided they follow proper protocols to ensure the patient can find care elsewhere.'),
    (v_topic_id, 'If a physician exercises "Conscientious Objection," they have an ethical duty to:', '["Tell the patient they are a sinner", "Provide the patient with information about alternative providers and ensure a safe ''Handoff'' or referral so the patient''s access to legal care is not blocked", "Hide their beliefs", "None of the above"]', 1, 'Objecting to a procedure does not excuse "Abandoning" the patient.'),
    (v_topic_id, 'A patient with "Schizophrenia" refuses a life-saving antibiotic for a pneumonia. They say: "I don''t want medicine because it will poison my chakras." The physician determines they lack capacity. Who makes the decision?', '["The doctor alone", "A surrogate (like a spouse or child) using the patient''s known values and best interests", "The police", "None of the above"]', 1, 'Incapacity triggers the need for a surrogate, regardless of the patient''s underlying diagnosis.'),
    (v_topic_id, 'A patient has a "Psychiatric Advance Directive" that says they do NOT want ECT (electroconvulsive therapy) under any circumstances. During a future psychotic episode, they are catatonic. The physician should:', '["Perform ECT anyway", "Honor the directive, as it was made when the patient had capacity specifically to guide their care during a future crisis", "Wait for the family to overrule it", "None of the above"]', 1, 'PADs are designed for exactly this situation.'),
    (v_topic_id, 'A patient refuses to disclose their "HIV Status" to their sexual partner. In some states, the physician:', '["Must stay silent", "May have a ''Duty to Warn'' or a legal framework to notify the partner anonymously (through the health department) to protect public health", "Must call the partner immediately and tell them the patient''s name", "None of the above"]', 1, 'Partner notification laws vary but generally prioritize the safety of the exposed individual while protecting the patient''s identity whenever possible.'),
    (v_topic_id, 'A patient is "Abusive" and "Threatening" to the clinic staff. The physician decides to "Fire" the patient. To avoid "Abandonment," the physician must:', '["Tell the patient to never come back", "Provide formal notice, a transition period (e.g., 30 days) of emergency-only care, and a list of alternative providers", "Call the police and do nothing else", "None of the above"]', 1, 'The patient-physician relationship is a contract that requires a specific process for termination.'),
    (v_topic_id, 'Which of the following is true about "Medical Futility" in US law?', '["It is a clear, national standard", "It is a complex area with no single definition, often requiring ethics committee review and a process for transferring the patient to another facility if the current team refuses treatment", "Doctors can always stop treatment if they want", "None of the above"]', 1, 'Futility cases often involve a procedural "Conflict Resolution" framework rather than a simple medical mandate.'),
    (v_topic_id, 'A surrogate insists on "Full Code" status for a patient with multi-organ failure and a 0% chance of survival from CPR. The physician believes CPR would be "Medically Inappropriate." The next step is:', '["Perform CPR anyway when the time comes", "Initiate a formal mediation process, involve the ethics committee, and if a transfer to another willing facility is not possible, some state laws (like Texas) provide a pathway to override the surrogate", "Sue the surrogate", "None of the above"]', 1, 'Futility disputes are managed through process, not just physician preference.'),
    (v_topic_id, 'Which principle is most involved in "Triage" decisions during a pandemic where ventilators are scarce?', '["Autonomy", "Justice (Utilitarianism)", "Beneficence", "Veracity"]', 1, 'Utilitarian justice aims to maximize the number of survivors when resources cannot meet the needs of all individuals.'),
    (v_topic_id, 'A patient refuses "Pain Medication" because they believe suffering is spiritually cleansing. The physician should:', '["Force the medication", "Respect the refusal while repeatedly offering comfort care options that align with the patient''s beliefs", "Tell them they are wrong", "None of the above"]', 1, 'Respecting autonomy includes respecting a patient''s unique religious or philosophical interpretation of suffering.'),
    (v_topic_id, 'A physician disagrees with a patient''s "Refusal of Life-Saving Treatment." The physician can:', '["Force the treatment", "Transfer the care of the patient to another physician who is willing to respect the refusal, if the current physician feels they cannot ethically comply", "Call the patient''s family to overrule them", "None of the above"]', 1, 'Physicians have the right to withdraw from a case (properly) if there is a fundamental moral conflict, but they cannot override the patient.'),
    (v_topic_id, 'Which of the following describes "Medical Battery"?', '["Failing to wash hands", "Performing a procedure without any consent at all (even if it was medically indicated and done well)", "A doctor hitting a nurse", "None of the above"]', 1, 'Battery is about the violation of the right to be left alone.'),
    (v_topic_id, 'A 15-year-old girl wants to start "Contraception" but her parents are against it. In most states, her right to consent is protected because:', '["She is almost an adult", "Contraception is considered a ''Sensitive Service'' where confidentiality is essential to prevent unintended pregnancies", "She has more rights than her parents", "None of the above"]', 1, 'Public health goals often override parental control in sensitive areas of minor health.'),
    (v_topic_id, 'A patient is "Brain Dead" but is a registered "Organ Donor." The family refuses to allow the donation. What is the legal standard?', '["The family always wins", "In many states, the patient''s ''First Person Consent'' (the donor registry) is legally binding and the OPO (Organ Procurement Organization) can proceed over family objection", "The doctor decides", "None of the above"]', 1, 'First Person Consent laws aim to honor the patient''s own prior choice regarding donation.'),
    (v_topic_id, 'A patient with "Severe Anorexia" refuses a life-saving feeding tube. The physician suspects the refusal is a symptom of the illness (distorted body image/perception). The physician should:', '["Respect the refusal", "Perform an emergency capacity assessment; if the illness is found to impair the reasoning process for this specific decision, the patient may lack capacity", "Let them die", "None of the above"]', 1, 'The impact of an eating disorder on "Appreciation" and "Reasoning" is a core clinical and ethical challenge.'),
    (v_topic_id, 'Which of the following is true regarding "Physician-Assisted Dying" (PAD) in the US?', '["It is legal in all 50 states", "It is legal in several states (like Oregon, Washington, California) but requires the patient to be terminal and to self-administer the medication", "It is the same as euthanasia", "None of the above"]', 1, 'PAD is highly regulated and only allowed in specific jurisdictions under strict criteria.'),
    (v_topic_id, 'A patient with capacity asks the doctor to "Kill them" with a lethal injection. This is:', '["Physician-assisted suicide", "Active Euthanasia (which is illegal in all 50 US states)", "A valid exercise of autonomy", "None of the above"]', 1, 'Direct active euthanasia (where the doctor performs the act) is universally illegal in the US.'),
    (v_topic_id, 'A 20-year-old patient refuses a blood transfusion and says: "I don''t believe in blood." They can provide no further reasoning. The physician should:', '["Respect the refusal", "Dig deeper; if the patient cannot explain *why* they don''t believe in it or the ''Reasoning'' is non-existent, they may lack the clinical elements of capacity", "Give blood anyway", "None of the above"]', 1, 'A "bare refusal" without reasoning is a red flag for a lack of capacity.'),
    (v_topic_id, 'A patient is in the "Military" and is ordered by their commander to have a specific medical test. Can they refuse?', '["No, the military is different", "Yes, but they may face ''Administrative'' or ''Legal'' consequences under the Uniform Code of Military Justice (UCMJ) for refusing a lawful order", "Only if they are an officer", "None of the above"]', 1, 'Military medicine involves unique tensions between individual rights and mission readiness.'),
    (v_topic_id, 'A "Prisoner" refuses a hunger strike and is near death. Can the prison force-feed them?', '["Always", "This is a highly controversial area; many ethics groups oppose force-feeding as a violation of bodily integrity, while courts often allow it for ''institutional safety and order", "Never", "None of the above"]', 1, 'The "Institutional Safety" interest of prisons often overrides individual autonomy in courts.'),
    (v_topic_id, 'A patient refuses to wear a "Mask" during a respiratory pandemic inside a hospital. The hospital can:', '["Force them to wear it", "Refuse to see the patient for non-emergent care and ask them to leave if they will not comply with safety protocols meant to protect others", "Call the police to arrest them", "None of the above"]', 1, 'Hospital policies designed for the protection of other patients are a valid limit on individual autonomy.'),
    (v_topic_id, 'Which of the following describes "Implicit Bias"?', '["A conscious choice to be mean", "Unconscious associations or stereotypes that can influence a physician''s judgment and quality of care without them realizing it", "A type of insurance", "None of the above"]', 1, 'Implicit bias is a significant factor in health disparities and must be actively managed.'),
    (v_topic_id, 'A patient is "Malnourished" because they can''t afford food. The physician should:', '["Tell them to get a job", "Address the ''Social Determinant of Health'' by involving a social worker and connecting the patient with community resources", "Give them a vitamin and send them home", "None of the above"]', 1, 'Modern medicine recognizes that social factors are as important as biological ones.'),
    (v_topic_id, 'A patient refuses a treatment because they want a "Second Opinion." The physician should:', '["Be offended", "Support the request and facilitate the transfer of records to the new provider", "Tell them it''s a waste of time", "None of the above"]', 1, 'A second opinion is a standard patient right and an exercise of autonomy.'),
    (v_topic_id, 'Which of the following is an example of "Non-compliant" behavior being a symptom of a disease?', '["A patient with ADHD forgetting their pills", "A patient with dementia getting lost on the way to the clinic", "A patient with depression lacking the energy to call for an appointment", "All of the above"]', 3, '"Non-compliance" is often a clinical problem that needs a medical solution, not a moral judgment.'),
    (v_topic_id, 'A patient with "Munchausen Syndrome" (Factitious Disorder) wants an unnecessary surgery. The physician should:', '["Do the surgery for the money", "Refuse the non-indicated procedure and focus on psychological support for the underlying condition", "Tell the patient they are a liar", "None of the above"]', 1, 'Performing harmful, unnecessary surgeries on a patient with factitious disorder is a violation of non-maleficence.'),
    (v_topic_id, 'Which of the following is true about "Placebo" use in clinical practice?', '["It is common and fine", "It is generally considered unethical as it involves ''Deception'' and undermines the trust of the patient-physician relationship", "It is required for every patient", "None of the above"]', 1, 'Deceptive placebos are a violation of the principle of Veracity.'),
    (v_topic_id, 'A "Whistleblower" in a hospital is someone who:', '["Plays an instrument", "Reports unethical or illegal behavior within their organization to a higher authority", "Is always fired", "None of the above"]', 1, 'Whistleblowing is a professional duty when patient safety or legal integrity is at stake.'),
    (v_topic_id, 'A patient is "Refusing" to follow a plan but won''t say why. The physician should:', '["Get angry", "Use ''Empathetic Inquiry'' to uncover hidden barriers like cost, fear, or cultural beliefs", "Ignore the patient", "None of the above"]', 1, 'Understanding the "Why" is essential for clinical problem-solving.'),
    (v_topic_id, 'A patient wants "Genetic Testing" but their insurance won''t cover it. The physician should:', '["Tell them they can''t have it", "Discuss the ''Pros and Cons'' of paying out-of-pocket and the implications for the patient and their family members", "Lied to the insurance", "None of the above"]', 1, 'Assisting the patient in navigating financial barriers is part of advocacy.'),
    (v_topic_id, 'Which of the following is true about "Standard of Care" across different countries?', '["It is the same everywhere", "It is ''Resource-Dependent''; what is standard in a high-resource setting may be impossible or inappropriate in a low-resource setting", "Only US standards matter", "None of the above"]', 1, 'Ethics must be interpreted within the context of available resources.'),
    (v_topic_id, 'A patient "Waiver" of liability signed before a surgery:', '["Protects the doctor from all lawsuits", "Does NOT protect the doctor from claims of ''Negligence'' if they fail to follow the standard of care", "Is required for all surgeries", "None of the above"]', 1, 'You cannot "contract away" your duty to provide safe, competent care.'),
    (v_topic_id, 'Which of the following is a "Vulnerable Population" that requires extra protection in consent?', '["Prisoners", "Children", "People with cognitive disabilities", "All of the above"]', 3, 'These groups are at higher risk of coercion or exploitation.'),
    (v_topic_id, 'A 40-year-old woman refuses a life-saving hysterectomy for uterine bleeding. Her husband demands the doctor do it. The doctor should:', '["Listen to the husband", "Respect the woman''s autonomy", "Wait for her to pass out", "None of the above"]', 1, 'A husband has no legal authority to overrule his competent wife''s medical decisions.'),
    (v_topic_id, 'A patient refuses to take their "Blood Pressure" medication. The physician should:', '["Threaten the patient", "Ask the patient what their ''Goals'' are for their health and see if a compromise plan can be reached", "Stop seeing the patient", "None of the above"]', 1, 'Goal-alignment is the key to managing chronic "non-compliance."'),
    (v_topic_id, 'Which of the following is true regarding "Patient Autonomy" in the UK vs the US?', '["The US is more paternalistic", "Both prioritize autonomy, but the UK legal system has traditionally given slightly more weight to the ''Professional Judgment'' of doctors (though this is changing)", "The UK has no autonomy", "None of the above"]', 1, 'Legal and cultural nuances exist across different healthcare systems.'),
    (v_topic_id, 'A patient is "Refusing" to be discharged from the hospital because they are lonely. The physician should:', '["Let them stay forever", "Coordinate with social work to find a safe and appropriate discharge plan to a community setting while explaining the need for hospital beds for acutely ill patients", "Call the police", "None of the above"]', 1, 'Justice involves the fair allocation of hospital beds.'),
    (v_topic_id, 'Which of the following describes "Compassionate Use" (Expanded Access) of a drug?', '["Giving drugs for free", "Allowing a terminally ill patient access to an experimental drug that has not yet been FDA-approved outside of a clinical trial", "A type of insurance", "None of the above"]', 1, 'Expanded access is a pathway for patients with no other options.'),
    (v_topic_id, 'A patient wants an "Antibiotic" for a cold. The physician refuses. This is a prioritized use of which principle?', '["Autonomy", "Stewardship (Justice/Non-maleficence)", "Veracity", "None of the above"]', 1, 'Preventing antibiotic resistance and avoiding unnecessary side effects is a duty that can override a patient''s request.'),
    (v_topic_id, 'A patient "Refuses" to see a doctor of a certain race/gender. The hospital should:', '["Force the doctor on them", "Generally accommodate the request if possible to ensure the patient is comfortable and can receive care, unless it causes a significant safety or staffing crisis", "Fire the patient", "None of the above"]', 1, 'Patient comfort is important, but hospitals also have a duty to protect their staff from discrimination and abuse.'),
    (v_topic_id, 'A "No-Fault" medical error system means:', '["The doctor is always right", "Patients receive compensation for injuries without having to prove ''Negligence'' in court (used in some countries and for vaccines in the US)", "No one is ever helped", "None of the above"]', 1, 'No-fault systems aim to improve reporting and provide faster help to injured patients.'),
    (v_topic_id, 'A patient with a terminal illness is "Suicidal." The physician should:', '["Help them die", "Assess if the suicidality is a symptom of a treatable depression or if it is a ''Rational'' response to their illness, and provide appropriate support", "Ignore it", "None of the above"]', 1, 'Terminal illness does not make suicide a "default" choice; it requires careful psychiatric and palliative assessment.'),
    (v_topic_id, 'Which of the following is true regarding "Medical Record" ownership?', '["The patient owns the physical paper", "The hospital/physician owns the physical/electronic record, but the patient has a legal right to access and obtain a copy of the information contained within it", "No one owns it", "None of the above"]', 1, 'The "data" belongs to the patient; the "vessel" belongs to the provider.'),
    (v_topic_id, 'A patient with capacity is "Refusing" to let the doctor talk to their family. The doctor should:', '["Talk to them anyway", "Respect the patient''s right to privacy and confidentiality", "Tell the family to sue", "None of the above"]', 1, 'Confidentiality is a cornerstone of the professional relationship.'),
    (v_topic_id, 'The final check for a "Refusal of Care" is ensuring the patient understands:', '["The cost of the hospital", "The specific risk of ''Death or Permanent Disability'' that may occur as a result of their choice", "The doctor''s name", "None of the above"]', 1, 'The gravity of the consequence must be clear for a refusal to be truly informed.');
